-- One-off import of products from STOCKLIST.xlsx → STOCK LIST sheet.
-- Generated by scripts/import_products_from_stocklist.py
-- Source: /Users/kiran/Downloads/STOCKLIST.xlsx
-- 483 products across 23 categories.
-- Apply once via Supabase SQL Editor.
-- Requires migrations 0009 + 0010 to be applied first.

-- ============================================================
-- STEP 0: Soft-delete the 6 seeded dummy products (by name).
-- ============================================================
update products
  set deleted_at = now()
  where deleted_at is null
  and name in (
    'Sunscreen SPF 50',
    'Vitamin C Serum',
    'Salicylic Acid Wash',
    'Retinol Cream 0.05%',
    'Hyaluronic Moisturiser',
    'Microneedling Tips'
  );

-- ============================================================
-- STEP 1: Bulk insert real products.
-- ============================================================
do $$
declare
  v_clinic uuid;
  v_before int;
  v_after int;
begin
  select id into v_clinic from clinics limit 1;
  if v_clinic is null then
    raise exception 'No clinic row. Apply 0005_seed_dev.sql first.';
  end if;
  select count(*) into v_before from products where deleted_at is null;

  ;

  select count(*) into v_after from products where deleted_at is null;
  raise notice 'Imported % product rows (% -> %).', v_after - v_before, v_before, v_after;
end$$;

